CREATE TABLE vpn_devices(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,public_key TEXT NOT NULL UNIQUE,address TEXT NOT NULL UNIQUE,state TEXT NOT NULL DEFAULT 'requested' CHECK(state IN ('requested','approved','revoked')),created TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE vpn_targets(id INTEGER PRIMARY KEY,service_id INTEGER NOT NULL REFERENCES services(id),label TEXT NOT NULL,cidr TEXT NOT NULL,protocol TEXT NOT NULL,ports TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE vpn_grants(id INTEGER PRIMARY KEY,device_id INTEGER NOT NULL REFERENCES vpn_devices(id),target_id INTEGER NOT NULL REFERENCES vpn_targets(id),state TEXT NOT NULL DEFAULT 'Pending' CHECK(state IN ('Pending','Approved','Denied','Revoked','Expired')),reason TEXT NOT NULL,target_label TEXT NOT NULL,service_name TEXT NOT NULL,explanation TEXT NOT NULL DEFAULT '',cidr TEXT NOT NULL DEFAULT '',protocol TEXT NOT NULL DEFAULT '',ports TEXT NOT NULL DEFAULT '',expires TEXT NOT NULL DEFAULT '',created TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX vpn_active_grant ON vpn_grants(device_id,target_id) WHERE state IN ('Pending','Approved');
CREATE TABLE vpn_status(id INTEGER PRIMARY KEY CHECK(id=1),revision TEXT NOT NULL DEFAULT '',public_key TEXT NOT NULL DEFAULT '',seen TEXT NOT NULL DEFAULT '');
INSERT INTO vpn_status(id) VALUES(1);
ALTER TABLE notifications ADD COLUMN device_id INTEGER REFERENCES vpn_devices(id);
CREATE TABLE vpn_history(id INTEGER PRIMARY KEY,grant_id INTEGER NOT NULL REFERENCES vpn_grants(id),actor_id INTEGER REFERENCES users(id),state TEXT NOT NULL,cidr TEXT NOT NULL,protocol TEXT NOT NULL,ports TEXT NOT NULL,expires TEXT NOT NULL,created TEXT NOT NULL);
